//! Built-in reference offline case (`demo_case_import`): twelve synthetic documents of the
//! fictional «ТОВ Приклад» (example.test) embedded in the binary and imported through the
//! regular `import_offline` path: no network, about a second on a phone. The archive is
//! generated by `qa/make_demo_case.py`.

use serde_json::{json, Value};

use crate::engine::Core;
use crate::util::arg_str;
use crate::CmdResult;

/// The embedded ZIP (`assets/demo_case.zip`).
const DEMO_CASE_ZIP: &[u8] = include_bytes!("../../assets/demo_case.zip");
/// Archive name shown in the import log.
const DEMO_CASE_FILE: &str = "priklad-reference-case.zip";
/// Default project name (Russian template of `core.demo_case.name`, shown in the UI language).
const DEMO_CASE_NAME: &str = "Эталонный кейс";
/// Scope target of the case.
const DEMO_CASE_DOMAIN: &str = "example.test";

/// `demo_case_import { name? }` → the `import_offline` result (`project`, `docs`, …) for a
/// new project named `name` (default: «Эталонный кейс» in the UI language) with scope
/// `example.test`.
pub(crate) async fn demo_case_import(core: &Core, a: &Value) -> CmdResult {
    let name = arg_str(a, "name")
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .map_or_else(
            || crate::i18n::localize(core.ui_lang(), DEMO_CASE_NAME),
            String::from,
        );
    let args = json!({
        "name": name,
        "domain": DEMO_CASE_DOMAIN,
        "files": [{ "name": DEMO_CASE_FILE, "data": foca_core::b64::encode(DEMO_CASE_ZIP) }],
    });
    let mut v = super::offline::import_offline(core, &args).await?;
    v["demo_case"] = json!(true);
    Ok(v)
}
